/* =============================================================================
 *  REAL HOLDEM POKER — 여성 딜러 10종 (200x200 JPEG · base64 내장)
 *  단일 HTML 번들에서도 100% 표시되도록 data URI 로 보관한다.
 *  생성: python3 tools/build_dealers.py
 * ========================================================================== */
(function (global) {
  'use strict';

  const LIST = [
    { id: 'hoodie', name: '지수', outfit: '캐주얼 후드', src: 'data:image/jpeg;base64,' },
    { id: 'suit', name: '서연', outfit: '블랙 베스트', src: 'data:image/jpeg;base64,' },
    { id: 'student', name: '하린', outfit: '프레피 교복', src: 'data:image/jpeg;base64,' },
    { id: 'cocktail', name: '유나', outfit: '버건디 드레스', src: 'data:image/jpeg;base64,' },
    { id: 'cardigan', name: '채원', outfit: '아이보리 니트', src: 'data:image/jpeg;base64,' },
    { id: 'rider', name: '다인', outfit: '레더 라이더', src: 'data:image/jpeg;base64,' },
    { id: 'tennis', name: '수아', outfit: '테니스 룩', src: 'data:image/jpeg;base64,' },
    { id: 'trench', name: '예린', outfit: '베이지 트렌치', src: 'data:image/jpeg;base64,' },
    { id: 'turtleneck', name: '나윤', outfit: '블랙 터틀넥', src: 'data:image/jpeg;base64,' },
    { id: 'hanbok', name: '지아', outfit: '퓨전 한복', src: 'data:image/jpeg;base64,' }
  ];

  const Dealers = {
    list: LIST,
    byId(id) {
      for (let i = 0; i < LIST.length; i++) if (LIST[i].id === id) return LIST[i];
      return LIST[0];
    },
    /* 방에 들어올 때마다 10종 중 랜덤 1명 (직전 딜러는 피한다) */
    random(excludeId) {
      const pool = LIST.filter(function (d) { return d.id !== excludeId; });
      return pool[Math.floor(Math.random() * pool.length)] || LIST[0];
    },
    preload() {
      LIST.forEach(function (d) { const im = new global.Image(); im.src = d.src; });
    }
  };

  global.Dealers = Dealers;
})(window);
